"""Portable CPU/Intel encoder settings. Benchmark profiles are specific to the CPU model."""
import hashlib, json, os, platform
from pathlib import Path

def cpu_name():
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,r"HARDWARE\DESCRIPTION\System\CentralProcessor\0") as k:
            return winreg.QueryValueEx(k,"ProcessorNameString")[0].strip()
    except (OSError,ImportError):
        return platform.processor() or "unknown"

def machine_key():
    return hashlib.sha256((cpu_name()+"|"+platform.machine()).encode()).hexdigest()[:20]

def portable_root():
    return Path(__file__).resolve().parents[4]

def profiles_path():
    return portable_root()/"config/encoder-profiles.json"

def selected_encoder():
    forced=os.getenv("SHORTSFLOW_FAST_ENCODER","auto").lower()
    if forced in ("cpu","intel"):
        return forced
    try:
        return json.loads(profiles_path().read_text(encoding="utf-8"))[machine_key()]["selected_encoder"]
    except (OSError,ValueError,KeyError,TypeError):
        return "cpu"

def save_choice(encoder,details):
    path=profiles_path()
    path.parent.mkdir(parents=True,exist_ok=True)
    try:
        profiles=json.loads(path.read_text(encoding="utf-8"))
    except (OSError,ValueError):
        profiles={}
    profiles[machine_key()]={"cpu":cpu_name(),"selected_encoder":encoder,**details}
    pending=path.with_suffix(".tmp")
    pending.write_text(json.dumps(profiles,indent=2),encoding="utf-8")
    os.replace(pending,path)

def device_args(encoder):
    return ["-init_hw_device","qsv:hw,child_device_type=dxva2"] if encoder=="intel" else []

def codec_args(encoder):
    # Same resolution/FPS/target bitrate. Different encoders still need visual quality review.
    codec=["-c:v","h264_qsv","-preset","veryfast"] if encoder=="intel" else ["-c:v","libx264","-preset","ultrafast"]
    return codec+["-b:v","4M","-maxrate","4M","-bufsize","8M","-threads","4"]
